#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

struct Point {
    double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    // Initialise the quadrant counters to zero.
    bins = {0, 0, 0, 0};

    // Parallelise the loop over points.
    #pragma omp parallel for
    for (size_t i = 0; i < points.size(); ++i) {
        const Point &p = points[i];

        // Determine the quadrant (axes are ignored).
        if (p.x > 0 && p.y > 0) {
            #pragma omp atomic
            ++bins[0];               // Quadrant I
        } else if (p.x < 0 && p.y > 0) {
            #pragma omp atomic
            ++bins[1];               // Quadrant II
        } else if (p.x < 0 && p.y < 0) {
            #pragma omp atomic
            ++bins[2];               // Quadrant III
        } else if (p.x > 0 && p.y < 0) {
            #pragma omp atomic
            ++bins[3];               // Quadrant IV
        }
    }
}
